const input = $input.first().json;
const payload = input.body._original_payload;
const rawFields = payload.fields || {};

// 医疗字段白名单：只保留需要 AI 扩写/生成的字段
const medicalFieldKeys = [
  'chief_complaint',           // 主诉
  'present_illness_history',   // 现病史
  'past_medical_history',      // 既往史
  'infectious_history',        // 流行病史
  'allergy_history',           // 过敏史
  'general_condition',         // 一般情况
  'examination_findings',      // 检查所见
  'auxiliary_examination',     // 辅助检查
  'diagnosis',                 // 诊断
  'treatment_plan',            // 治疗计划
  'treatment',                 // 治疗文稿
  'tooth_positions',           // 治疗牙位
  'medical_advice',            // 医嘱
  'prescription',              // 处方
  'record_tags',               // 病历标签
  'image_summary',             // 影像摘要
  'notes'                      // 病历备注
];

// 构建干净的医疗字段对象，字符串自动 trim
const 医疗字段 = {};
medicalFieldKeys.forEach(key => {
  const value = rawFields[key];
  医疗字段[key] = (typeof value === 'string') ? value.trim() : value;
});

// AI 写病历时需要引用的患者基础信息（从原始数据提取，但不参与扩写）
const 患者信息 = {
  patient_name: (rawFields.patient_name || '').trim(),
  visit_date: (rawFields.visit_date || '').trim(),
  record_type: (rawFields.record_type || '').trim(),
  tooth_positions: (rawFields.tooth_positions || '').trim(),
  doctor_name: (rawFields.doctor_name || '').trim()
};

// 统计医疗字段中已填写的字段（方便调试）
const 已填写字段 = Object.entries(医疗字段).filter(([k, v]) => {
  if (v === null || v === undefined) return false;
  if (typeof v === 'string' && v === '') return false;
  if (Array.isArray(v) && v.length === 0) return false;
  return true;
}).map(([k]) => k);

// 返回给下游的干净数据结构
return [{
  json: {
    // 路由信息
    治疗项目: payload.scene_name || '',
    治疗步骤: payload.step_name || '',
    scene_id: payload.scene_id || '',
    step_id: payload.step_id || '',
    account_id: payload.account_id || '',

    // 患者基础信息（供提示词引用）
    患者信息,

    // 纯医疗字段（供 AI 扩写）
    医疗字段,

    // 调试信息
    已填写字段数: 已填写字段.length,
    已填写字段列表: 已填写字段
  }
}];

